mapper.select:
SELECT m.*, u.user_name, u.phone FROM messages m LEFT JOIN tb_user u ON m.user_id = u.user_id
and m.title like concat('%', #{params.title} ,'%')
and m.content like concat('%', #{params.content} ,'%')
and m.type = #{params.type}
and m.user_id = #{params.userId}
and m.is_read = #{params.isRead}
and m.create_time between #{params.startTime} and #{params.endTime}
and u.user_name like concat('%', #{params.userName} ,'%')
and u.phone like concat('%', #{params.phone} ,'%')
ORDER BY m.create_time DESC
